-- Thomas Turner (profileID=20) — ENDORSEMENTS
-- Generated by endorsement_framework.py

-- STEP 1: PHRASE_ENDORSE rows for all Thomas Turner phrasings

SELECT p.argumentID, p.phrasingID, 20, 100, 1
FROM PHRASING p
WHERE p.coinedBy = 20
  AND NOT EXISTS (
    SELECT 1 FROM PHRASE_ENDORSE pe
    WHERE pe.profileID = 20 AND pe.argumentID = p.argumentID
  );

-- STEP 2: Endorsement chains (Because / Therefore / Rebuttal)

DELETE FROM ENDORSEMENT WHERE profileID=20 AND targArgID IN (80,104,107,123,134,135,136,140,142,143,197,226,278,288,297,315,321,322,323,326,328,334,335,341,367,368,369,400,401,404,405,407,414,420,422,459,460,494,530,543,544,560,561,574,596,606,609,667,696,698,701,702,727,736,739,740,790,793,863);


-- STEP 3: Sync PHRASE_ENDORSE active flag with opinion acceptance

UPDATE PHRASE_ENDORSE pe
JOIN OPINION o ON pe.argumentID = o.argumentID AND o.profileID = 20
SET pe.active = o.acceptance
WHERE pe.profileID = 20;

SELECT 'Done: endorsements for profileID=20' AS status;